import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        long[] a = new long[N];
        long[] b = new long[N];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            b[i] = Long.parseLong(st.nextToken());
        }

        long baseSum = 0;
        long[] gain = new long[N];

        for (int i = 0; i < N; i++) {
            if (b[i] <= a[i]) {
                baseSum += a[i] - b[i];
                gain[i] = b[i];
            } else {
                gain[i] = a[i];
            }
        }

        Integer[] order = new Integer[N];
        for (int i = 0; i < N; i++) {
            order[i] = i;
        }

        Arrays.sort(order, (x, y) -> Long.compare(gain[y], gain[x]));

        long[] pref = new long[N + 1];
        int[] rank = new int[N];

        for (int pos = 0; pos < N; pos++) {
            int idx = order[pos];
            rank[idx] = pos + 1;
            pref[pos + 1] = pref[pos] + gain[idx];
        }

        long totalGain = pref[N];
        int kk = Math.min(K, N - 1);
        long ans = Long.MIN_VALUE;

        for (int last = 0; last < N; last++) {
            long cur = a[last] + baseSum;

            if (b[last] <= a[last]) {
                cur -= a[last] - b[last];
            }

            long top;
            if (kk == 0) {
                top = 0;
            } else if (kk >= N - 1) {
                top = totalGain - gain[last];
            } else {
                int r = rank[last];
                if (r <= kk) {
                    top = pref[kk + 1] - gain[last];
                } else {
                    top = pref[kk];
                }
            }

            ans = Math.max(ans, cur + top);
        }

        System.out.println(ans);
    }
}
